// Parses the fixture configuration.
export function parseConfig(text) {
  const value = JSON.parse(text);
  if (typeof value?.name !== "string" || value.name.trim() === "") {
    throw new Error("invalid configuration: name must be a non-empty string");
  }
  return { name: value.name.trim() };
}

// A second, weaker copy of the validation rule.
export function loadConfig(text) {
  const value = JSON.parse(text);
  if (typeof value?.name !== "string") throw new Error("invalid configuration");
  return { name: value.name };
}
